import Foundation

/// The text of every generated file, for one checked spec.
struct Templates {
    let spec: AppProjectSpec
    let name: String
    /// The checkout's root.
    let checkout: String

    init(_ spec: AppProjectSpec) {
        self.spec = spec
        name = spec.name
        switch spec.kajo {
        case .path(let p): checkout = p.hasSuffix("/") ? String(p.dropLast()) : p
        }
    }

    /// The development half a Debug build links: the checkout's prebuilt
    /// frameworks, by name. Xcode links a package product in every
    /// configuration it is linked in at all, so the product is a dependency
    /// with `link: false` (Xcode still makes the frameworks available to the
    /// compiler and the linker) and only Debug's linker flags name them.
    static let developmentFrameworks = "-framework KajoAppDevelopment -framework KajoDev"

    var gitignore: String {
        """
        # Generated by kajo new.
        .build/
        DerivedData/
        xcuserdata/
        *.xcuserstate

        """
    }

    var targetsLine: String {
        switch (spec.has(.macOS), spec.has(.iOS)) {
        case (true, true): "`\(name)-macOS` and `\(name)-iOS`\n  over the same `src/`"
        case (true, false): "`\(name)-macOS` over `src/`"
        default: "`\(name)-iOS` over `src/`"
        }
    }

    var readme: String {
        """
        # \(name)

        A Kajo app made by `kajo new`. The app is Smalltalk in `src/` (Tonel,
        package `\(name)`); the Swift in `Sources/App.swift` only hands the
        bundled image to Kajo.

        - `project.yml` is the xcodegen spec: \(targetsLine). Make the Xcode project with `xcodegen generate`
          (the Kajo app does it for you).
        - Kajo is the prebuilt Release build in `\(checkout)/Prebuilt`, the one
          local package the project names: both configurations run the same
          optimized VM, and nothing is compiled or fetched for it.
        - Debug bundles a development image of the kernel and `src/` and serves
          the Kajo development protocol from launch (Bonjour `_kajo-dev._tcp`,
          named "\(name) on <device>"). Its pairing screen is a shake away on
          iOS and in the app menu (Pairing…, shift-command-P) on the Mac.
        - Release bundles a sealed release image of the same sources and links
          no development code; it does not serve.
        - The images are built by `scripts/build-images.sh` in a build phase,
          with the checkout's prebuilt `kajo`.

        Develop live from the Mac: run the Debug build, read the token off its
        pairing screen, and connect the tools or the CLI to `bonjour:<name>`;
        an accepted change is written to `src/` when the client is given
        `--project src`. A relaunch starts from the bundled image again, so
        build again to keep what you changed.

        """
    }

    var mainSwift: String {
        """
        // The app's whole Swift, the same for every target: the bundled image
        // to Kajo. Debug adds the development half, which serves the
        // development protocol from launch; Release links none of it.

        import KajoApp
        #if DEBUG
        import KajoAppDevelopment
        #endif

        @main enum Main {
            static func main() {
                let app = KajoAppConfiguration(name: "\(name)", appClass: "\(name)App")
                #if DEBUG
                KajoApplication.main(app, development: Development())
                #else
                KajoApplication.main(app)
                #endif
            }
        }

        """
    }

    var teamSetting: String {
        spec.team.map { "\n    DEVELOPMENT_TEAM: \($0)" } ?? ""
    }

    var platformsLine: String {
        switch (spec.has(.macOS), spec.has(.iOS)) {
        case (true, true): "for the Mac and for iPhone and\n# iPad"
        case (true, false): "for the Mac"
        default: "for iPhone and iPad"
        }
    }

    var deploymentTargets: String {
        (spec.has(.iOS) ? "    iOS: \"18.0\"\n" : "") + (spec.has(.macOS) ? "    macOS: \"15.0\"\n" : "")
    }

    /// The dependencies both targets have: the prebuilt runtime, and the
    /// development half built for the compiler but linked by Debug alone.
    var dependencies: String {
        """
            dependencies:
              - package: Kajo
                product: KajoApp
              - package: Kajo
                product: KajoAppDevelopment
                link: false
            postBuildScripts:
              - name: Build the image
                basedOnDependencyAnalysis: false
                script: |
                  "$PROJECT_DIR/scripts/build-images.sh"

        """
    }

    var macTarget: String {
        guard spec.has(.macOS) else { return "" }
        return """
          \(name)-macOS:
            type: application
            platform: macOS
            sources: [Sources]
            settings:
              base:
                PRODUCT_MODULE_NAME: \(name)
                CODE_SIGN_IDENTITY: "-"
                ENABLE_HARDENED_RUNTIME: NO
                # The prebuilt Kajo is Apple silicon only.
                ARCHS: arm64
              configs:
                Debug:
                  INFOPLIST_FILE: Info-macOS-Debug.plist
                  OTHER_LDFLAGS: $(inherited) \(Templates.developmentFrameworks)
                Release:
                  INFOPLIST_FILE: Info-macOS-Release.plist

        """ + dependencies
    }

    var iosTarget: String {
        guard spec.has(.iOS) else { return "" }
        return """
          \(name)-iOS:
            type: application
            platform: iOS
            sources: [Sources]
            settings:
              base:
                PRODUCT_MODULE_NAME: \(name)
                TARGETED_DEVICE_FAMILY: "1,2"
              configs:
                Debug:
                  INFOPLIST_FILE: Info-iOS-Debug.plist
                  OTHER_LDFLAGS: $(inherited) \(Templates.developmentFrameworks)
                Release:
                  INFOPLIST_FILE: Info-iOS-Release.plist

        """ + dependencies
    }

    var projectYML: String {
        """
        # Generated by kajo new: the \(name) app \(platformsLine), over one Tonel directory (src/). `xcodegen generate`
        # writes \(name).xcodeproj. Both configurations link the prebuilt Release
        # Kajo of the checkout the one local package names; Debug also links its
        # development half and bundles a development image, Release links neither
        # and bundles a release image.
        name: \(name)
        options:
          deploymentTarget:
        \(deploymentTargets)packages:
          Kajo:
            path: "\(checkout)/Prebuilt"
        settings:
          base:\(teamSetting)
            CODE_SIGN_STYLE: Automatic
            SWIFT_VERSION: "6.0"
            ENABLE_USER_SCRIPT_SANDBOXING: NO
            GENERATE_INFOPLIST_FILE: NO
            PRODUCT_NAME: \(name)
            PRODUCT_BUNDLE_IDENTIFIER: \(spec.bundleIdentifier)
        targets:
        \(macTarget)\(iosTarget)
        """
    }

    /// The keys only a development build has: the Bonjour service it
    /// advertises and why it is on the local network.
    func developmentKeys(_ debug: Bool) -> String {
        guard debug else { return "" }
        return """
        \t<key>NSBonjourServices</key>
        \t<array>
        \t\t<string>_kajo-dev._tcp</string>
        \t</array>
        \t<key>NSLocalNetworkUsageDescription</key>
        \t<string>The development build of \(name) serves the Kajo development protocol to the developer's tools on the local network.</string>

        """
    }

    /// The plist's opening and the keys both platforms share; `first` are
    /// keys that sort before them.
    func plistHead(_ first: String = "") -> String {
        """
        <?xml version="1.0" encoding="UTF-8"?>
        <!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
        <plist version="1.0">
        <dict>
        \(first)\t<key>CFBundleDevelopmentRegion</key>
        \t<string>$(DEVELOPMENT_LANGUAGE)</string>
        \t<key>CFBundleDisplayName</key>
        \t<string>\(name)</string>
        \t<key>CFBundleExecutable</key>
        \t<string>$(EXECUTABLE_NAME)</string>
        \t<key>CFBundleIdentifier</key>
        \t<string>$(PRODUCT_BUNDLE_IDENTIFIER)</string>
        \t<key>CFBundleInfoDictionaryVersion</key>
        \t<string>6.0</string>
        \t<key>CFBundleName</key>
        \t<string>$(PRODUCT_NAME)</string>
        \t<key>CFBundlePackageType</key>
        \t<string>APPL</string>
        \t<key>CFBundleShortVersionString</key>
        \t<string>1.0</string>
        \t<key>CFBundleVersion</key>
        \t<string>1</string>

        """
    }

    func iosPlist(debug: Bool) -> String {
        // ProMotion: without the key an iPhone app's frames are capped at
        // 60 Hz (an iPad renders 120 Hz either way); the shell's spec has it.
        plistHead("\t<key>CADisableMinimumFrameDurationOnPhone</key>\n\t<true/>\n") + developmentKeys(debug) + """
        \t<key>UIApplicationSceneManifest</key>
        \t<dict>
        \t\t<key>UIApplicationSupportsMultipleScenes</key>
        \t\t<false/>
        \t\t<key>UISceneConfigurations</key>
        \t\t<dict>
        \t\t\t<key>UIWindowSceneSessionRoleApplication</key>
        \t\t\t<array>
        \t\t\t\t<dict>
        \t\t\t\t\t<key>UISceneConfigurationName</key>
        \t\t\t\t\t<string>Default</string>
        \t\t\t\t\t<key>UISceneDelegateClassName</key>
        \t\t\t\t\t<string>KajoSceneDelegate</string>
        \t\t\t\t</dict>
        \t\t\t</array>
        \t\t</dict>
        \t</dict>
        \t<key>UILaunchScreen</key>
        \t<dict/>
        \t<key>UIRequiresFullScreen</key>
        \t<true/>
        \t<key>UISupportedInterfaceOrientations</key>
        \t<array>
        \t\t<string>UIInterfaceOrientationPortrait</string>
        \t</array>
        </dict>
        </plist>

        """
    }

    func macPlist(debug: Bool) -> String {
        plistHead() + developmentKeys(debug) + """
        \t<key>LSMinimumSystemVersion</key>
        \t<string>15.0</string>
        \t<key>NSHighResolutionCapable</key>
        \t<true/>
        \t<key>NSPrincipalClass</key>
        \t<string>NSApplication</string>
        </dict>
        </plist>

        """
    }

    var buildImages: String {
        """
        #!/bin/zsh
        # Generated by kajo new: the image of the configuration being built, with
        # the checkout's prebuilt kajo, into the app's resources (kajo/app.img).
        # Debug: a development image of the kernel and src/ (it serves the
        # development protocol). Release: a release image of the same sources
        # (sealed; it does not serve, and its methods cannot change). An image is
        # built again only when src/, the kernel or kajo is newer. No compiler,
        # no network. By hand: scripts/build-images.sh <resources dir> Debug|Release
        set -euo pipefail
        project=${0:A:h:h}
        kajo_root='\(checkout)'
        kajo=$kajo_root/Prebuilt/bin/kajo
        out=${1:-$TARGET_BUILD_DIR/$UNLOCALIZED_RESOURCES_FOLDER_PATH}/kajo
        config=${2:-$CONFIGURATION}
        cache=$project/.build/kajo
        mkdir -p $cache $out
        [[ -x $kajo ]] || { print "error: no prebuilt kajo at $kajo (is the Kajo checkout still there? Open the Kajo app once)"; exit 1; }
        if [[ $config == Release ]]; then kind=release; flags=(--release); else kind=development; flags=(); fi
        img=$cache/app-$kind.img
        if [[ ! -f $img || -n $(find $project/src $kajo_root/kernel $kajo -newer $img -print -quit) ]]; then
          $kajo build-image -o $img.new $flags $kajo_root/kernel $project/src > $cache/image.log 2>&1 || { cat $cache/image.log; exit 1; }
          mv $img.new $img
        fi
        cp $img $out/app.img

        """
    }

    var packageST: String {
        "Package { #name : #\(name) }\n"
    }

    var appClass: String {
        """
        "The app kajo new made: a window with a label and a button that changes the label. open builds the window and starts the event loop; pressed is the button's action."
        Class {
        \t#name : #\(name)App,
        \t#superclass : #Object,
        \t#classInstVars : [
        \t\t'window',
        \t\t'label',
        \t\t'button',
        \t\t'presses'
        \t],
        \t#category : #\(name)
        }

        { #category : #accessing }
        \(name)App class >> labelText [
        \t^ label text
        ]

        { #category : #actions }
        \(name)App class >> pressed [
        \t"The button's action: count the press and show the count."
        \tpresses := presses + 1.
        \tlabel text: 'Pressed ' , presses printString , ' times'
        ]

        { #category : #opening }
        \(name)App class >> open [
        \t"Build and show the window, then start the event loop."
        \tpresses := 0.
        \twindow := Window new.
        \twindow title: '\(name)'.
        \twindow x: 80 y: 80 width: 360 height: 220.
        \tlabel := window add: Label new.
        \tlabel x: 20 y: 60 width: 320 height: 28.
        \tlabel text: 'Hello from Kajo'.
        \tbutton := window add: Button new.
        \tbutton x: 20 y: 110 width: 200 height: 36.
        \tbutton title: 'Press me'.
        \tbutton action: [self pressed].
        \twindow show.
        \tUIEventLoop start
        ]

        """
    }

    var appTest: String {
        """
        "The test kajo new made for \(name)App: a press changes the label."
        Class {
        \t#name : #\(name)AppTest,
        \t#superclass : #TestCase,
        \t#category : #\(name)
        }

        { #category : #tests }
        \(name)AppTest >> testPressingChangesTheLabel [
        \t\(name)App open.
        \tself assert: \(name)App labelText equals: 'Hello from Kajo'.
        \t\(name)App pressed.
        \tself assert: \(name)App labelText equals: 'Pressed 1 times'
        ]

        """
    }
}
